27	// 16MiB - maximum length in bytes of a string to be encoded.
28	#define MAX_ENCODE_BYTE_LEN 16777216
29	// Number of bytes which are added to the base string before encryption.
30	#define OVERHEAD_BYTES 5
31	
32	static mc_affix_set_t *generate_prefix_or_suffix_tree(const mc_utf8_string_with_bad_char_t *base_str,
33	                                                      uint32_t unfolded_byte_len,
34	                                                      uint32_t lb,
35	                                                      uint32_t ub,
36	                                                      bool is_prefix,
37	                                                      uint32_t *out_msize) {
38	    BSON_ASSERT_PARAM(base_str);
39	    BSON_ASSERT_PARAM(out_msize);
40	    // We encrypt (unfolded string + 5 bytes of extra BSON info) with a 16-byte block cipher.
41	    // PKCS7 adds an extra 16-byte padding for 16-byte aligned plaintext lengths.
42	    uint32_t encrypted_len = 16 * (uint32_t)((unfolded_byte_len + OVERHEAD_BYTES + 16) / 16);
43	    // Max len of a string that has this encrypted len.
44	    uint32_t padded_len = encrypted_len - OVERHEAD_BYTES;
45	    if (padded_len < lb) {
46	        // No valid substrings, return empty tree
47	        return NULL;
48	    }
49	
50	    // Total number of substrings
51	    uint32_t msize = BSON_MIN(padded_len, ub) - lb + 1;
52	    uint32_t folded_codepoint_len = base_str->codepoint_len - 1; // remove one codepoint for 0xFF
53	    uint32_t real_max_len = BSON_MIN(folded_codepoint_len, ub);
54	    // Number of actual substrings, excluding padding
55	    uint32_t real_substrings = real_max_len >= lb ? real_max_len - lb + 1 : 0;
56	    // If real_substrings and msize differ, we need to insert padding, so allocate one extra slot.
57	    uint32_t set_size = real_substrings == msize ? real_substrings : real_substrings + 1;
58	    mc_affix_set_t *set = mc_affix_set_new(base_str, set_size);
59	    uint32_t n_inserted = 0;
60	    for (uint32_t i = lb; i < real_max_len + 1; i++, n_inserted++) {
61	        if (is_prefix) {
62	            // [0, lb), [0, lb + 1), ..., [0, min(len, ub))
63	            BSON_ASSERT(mc_affix_set_insert(set, 0, i));
64	        } else {
65	            // [len - lb, len), [len - lb - 1, len), ..., [max(0, len - ub), len)
66	            BSON_ASSERT(mc_affix_set_insert(set, folded_codepoint_len - i, folded_codepoint_len));
67	        }
68	    }
69	    if (msize != real_substrings) {
70	        // Insert padding to get to msize
71	        BSON_ASSERT(mc_affix_set_insert_base_string(set, msize - real_substrings));
72	        n_inserted++;
73	    }
74	    BSON_ASSERT(n_inserted == set_size);
75	    *out_msize += msize;
76	    return set;
77	}
78	
79	static mc_affix_set_t *generate_suffix_tree(const mc_utf8_string_with_bad_char_t *base_str,
80	                                            uint32_t unfolded_byte_len,
81	                                            const mc_FLE2SuffixInsertSpec_t *spec,
82	                                            uint32_t *out_msize) {
83	    BSON_ASSERT_PARAM(spec);
84	    return generate_prefix_or_suffix_tree(base_str, unfolded_byte_len, spec->lb, spec->ub, false, out_msize);
85	}
