87	static mc_affix_set_t *generate_prefix_tree(const mc_utf8_string_with_bad_char_t *base_str,
88	                                            uint32_t unfolded_byte_len,
89	                                            const mc_FLE2PrefixInsertSpec_t *spec,
90	                                            uint32_t *out_msize) {
91	    BSON_ASSERT_PARAM(spec);
92	    return generate_prefix_or_suffix_tree(base_str, unfolded_byte_len, spec->lb, spec->ub, true, out_msize);
93	}
