109	static mc_substring_set_t *generate_substring_tree(const mc_utf8_string_with_bad_char_t *base_str,
110	                                                   uint32_t unfolded_byte_len,
111	                                                   const mc_FLE2SubstringInsertSpec_t *spec,
112	                                                   uint32_t *out_msize) {
113	    BSON_ASSERT_PARAM(base_str);
114	    BSON_ASSERT_PARAM(spec);
115	    BSON_ASSERT_PARAM(out_msize);
116	    // We encrypt (unfolded string + 5 bytes of extra BSON info) with a 16-byte block cipher.
117	    // PKCS7 adds an extra 16-byte padding for 16-byte aligned plaintext lengths.
118	    uint32_t encrypted_len = 16 * (uint32_t)((unfolded_byte_len + OVERHEAD_BYTES + 16) / 16);
119	    // Max len of a string that has this encrypted len.
120	    uint32_t padded_len = encrypted_len - OVERHEAD_BYTES;
121	    if (padded_len < spec->lb) {
122	        // No valid substrings, return empty tree
123	        return NULL;
124	    }
