127	    // justifies why that calculation and this calculation are equivalent.
128	    // At this point, it is established that:
129	    //     beta <= mlen
130	    //     lb <= padded_len
131	    //     lb <= ub <= mlen
132	    //
133	    // So, the following formula for msize in the OST paper:
134	    //     maxkgram_1 = sum_(j=lb, ub, (mlen - j + 1))
135	    //     maxkgram_2 = sum_(j=lb, min(ub, padded_len), (padded_len - j + 1))
136	    //     msize      = min(maxkgram_1, maxkgram_2)
