142	    //     maxkgram_2 = sum_(j=lb, padded_len, (padded_len - j + 1))    # less or equal to maxkgram_1
143	    //     msize      = maxkgram_2
144	    // and if padded_len > ub, then it follows that:
145	    //     maxkgram_1 = sum_(j=lb, ub, (mlen - j + 1))          # as above
146	    //     maxkgram_2 = sum_(j=lb, ub, (padded_len - j + 1))        # same sum bounds as maxkgram_1
147	    //     msize      = sum_(j=lb, ub, (min(mlen, padded_len) - j + 1))
