41	    ret->codepoint_offsets[ret->codepoint_len++] = (uint32_t)(end - buf);
42	    // realloc to save some space
43	    ret->codepoint_offsets = bson_realloc(ret->codepoint_offsets, sizeof(uint32_t) * ret->codepoint_len);
44	    return ret;
